def choose_move(observation):
    def sgn(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return [int(v[0]), int(v[1])]
        return None

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def step_away(a, b):
        return [sgn(a[0] - b[0]), sgn(a[1] - b[1])]

    env = observation.get("environment_name", "resource_collection")
    self_pos = pos(observation.get("self_position")) or [0, 0]
    opp_pos = pos(observation.get("opponent_position")) or [self_pos[0], self_pos[1]]

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        w = int(observation.get("grid_width", 5) or 5)
        h = int(observation.get("grid_height", 5) or 5)
        corners = [[0, 0], [0, h - 1], [w - 1, 0], [w - 1, h - 1]]
        target = max(corners, key=lambda c: dist(c, opp_pos))
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        parsed = []
        for t in targets:
            p = pos(t)
            if p is not None:
                parsed.append(p)
        if parsed:
            target = min(parsed, key=lambda c: dist(c, self_pos))
            return step_toward(self_pos, target)
        center = pos([observation.get("grid_width", 1) // 2, observation.get("grid_height", 1) // 2])
        if center:
            return step_toward(self_pos, center)
        return step_away(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    parsed = []
    for r in resources:
        p = pos(r)
        if p is not None:
            parsed.append(p)

    if parsed:
        best = None
        best_score = None
        for r in parsed:
            score = dist(self_pos, r)
            if opp_pos != self_pos:
                score -= 0.25 * dist(opp_pos, r)
            if best is None or score < best_score:
                best = r
                best_score = score
        if best is not None:
            return step_toward(self_pos, best)

    if obs := observation.get("opponent_velocity"):
        ov = pos(obs)
        if ov is not None:
            return step_away(self_pos, opp_pos)

    return step_toward(self_pos, opp_pos)

